#!/usr/bin/env bash
set -euo pipefail

cd "$(dirname "$0")/.."

REPO_ROOT="$(git rev-parse --show-toplevel 2>/dev/null || true)"
if [ -n "$REPO_ROOT" ] && [ -f "$REPO_ROOT/.venv/bin/activate" ]; then
  # shellcheck disable=SC1091
  . "$REPO_ROOT/.venv/bin/activate"
fi

set -a
[ -f .env ] && . ./.env
set +a

: "${DEEPGRAM_API_KEY:?DEEPGRAM_API_KEY is required for inspector e2e}"
: "${OPENAI_API_KEY:?OPENAI_API_KEY is required for inspector e2e}"
: "${RASA_PRO_LICENSE:?RASA_PRO_LICENSE is required for inspector e2e}"

[ -n "${CI:-}" ] && export BROWSER=echo

CALM_AGENT_DIR=agents/calm
MANTLE_AGENT_DIR=agents/mantle
MCP_PID=""
RASA_PID=""
MANTLE_RASA_PID=""
CLEANUP_DONE=0

kill_pid() {
  local pid=$1
  [ -z "$pid" ] && return 0
  kill -TERM "$pid" 2>/dev/null || true
  for _ in $(seq 1 10); do
    kill -0 "$pid" 2>/dev/null || return 0
    sleep 0.2
  done
  kill -KILL "$pid" 2>/dev/null || true
}

cleanup() {
  if [ "$CLEANUP_DONE" = 1 ]; then
    return 0
  fi
  CLEANUP_DONE=1

  echo ""
  echo "Stopping e2e services..."
  kill_pid "$RASA_PID"
  kill_pid "$MANTLE_RASA_PID"
  kill_pid "$MCP_PID"

  set +e
  wait "$RASA_PID" "$MANTLE_RASA_PID" "$MCP_PID" 2>/dev/null
  set -e
}

on_signal() {
  cleanup
  exit "$1"
}

trap cleanup EXIT
trap 'on_signal 130' INT
trap 'on_signal 143' TERM

wait_for_url() {
  local url=$1
  local name=$2
  for _ in $(seq 1 60); do
    if curl -sf "$url" >/dev/null; then
      echo "$name ready"
      return 0
    fi
    sleep 1
  done
  echo "$name failed to start within 60s"
  return 1
}

if ! python -c "from mcp.server.fastmcp import FastMCP" 2>/dev/null; then
  echo "Mock MCP requires the repo venv (mcp package). From repo root: make install && source .venv/bin/activate" >&2
  exit 1
fi

echo "Starting mock MCP..."
python mock-mcp/server.py &
MCP_PID=$!

wait_for_url "http://127.0.0.1:8765/health" "Mock MCP"

echo "Training mantle and CALM agents in parallel..."
(cd "$MANTLE_AGENT_DIR" && rasa train) &
MANTLE_TRAIN_PID=$!
(cd "$CALM_AGENT_DIR" && rasa train) &
CALM_TRAIN_PID=$!

MANTLE_TRAIN_STATUS=0
CALM_TRAIN_STATUS=0
wait "$MANTLE_TRAIN_PID" || MANTLE_TRAIN_STATUS=$?
wait "$CALM_TRAIN_PID" || CALM_TRAIN_STATUS=$?
if [ "$MANTLE_TRAIN_STATUS" -ne 0 ] || [ "$CALM_TRAIN_STATUS" -ne 0 ]; then
  echo "Training failed (mantle=$MANTLE_TRAIN_STATUS calm=$CALM_TRAIN_STATUS)" >&2
  exit 1
fi
echo "Both agents trained"

# Start both inspectors together. Wait Mantle then CALM; SST also waits on both
# ports so Playwright does not start while either inspect is still coming up.
echo "Starting mantle inspector on port 5006 and CALM inspector on port 5005..."
pushd "$MANTLE_AGENT_DIR" >/dev/null
rasa inspect --port 5006 &
MANTLE_RASA_PID=$!
popd >/dev/null

pushd "$CALM_AGENT_DIR" >/dev/null
rasa inspect --port 5005 &
RASA_PID=$!
popd >/dev/null

wait_for_url "http://localhost:5006" "Mantle inspector"
wait_for_url "http://localhost:5005" "CALM inspector"

if [ -z "${CI:-}" ]; then
  cat <<EOF

E2E environment ready.
  Mock MCP:         http://127.0.0.1:8765/health
  CALM inspector:   http://localhost:5005/webhooks/inspector/inspect.html
  Mantle inspector: http://localhost:5006/webhooks/inspector/inspect.html

In another terminal, run:
  yarn e2e:only

Press Ctrl+C to stop services.

EOF
fi

wait "$MCP_PID" "$RASA_PID" "$MANTLE_RASA_PID"
